1	#include "amr_dispatcher_core/catalog/station_catalog.hpp"
2	
3	#include <algorithm>
4	#include <cmath>
5	#include <fstream>
6	#include <limits>
7	#include <sstream>
8	#include <string>
9	#include <unordered_set>
10	#include <vector>
11	
12	namespace amr_dispatcher_core::catalog {
13	namespace {
14	
15	std::string Trim(const std::string& value) {
16	  auto first = value.find_first_not_of(" \t\r\n");
17	  if (first == std::string::npos) {
18	    return "";
19	  }
20	  auto last = value.find_last_not_of(" \t\r\n");
21	  std::string s = value.substr(first, last - first + 1);
22	  // 去除 YAML 引号包裹：例如 "station_pickup_A" 或 'station_pickup_A'
23	  if (s.size() >= 2 && ((s.front() == '"' && s.back() == '"') || (s.front() == '\'' && s.back() == '\''))) {
24	    s = s.substr(1, s.size() - 2);
25	  }
26	  return s;
27	}
28	
29	std::optional<std::string> ValueAfterColon(const std::string& line, const std::string& key) {
30	  const std::string prefix = key + ":";
31	  if (line.rfind(prefix, 0) != 0) {
32	    return std::nullopt;
33	  }
34	  return Trim(line.substr(prefix.size()));
35	}
36	
37	std::optional<double> ParseDouble(const std::string& value) {
38	  std::istringstream parser(value);
39	  double result = 0.0;
40	  parser >> result;
41	  if (parser.fail() || !std::isfinite(result)) {
42	    return std::nullopt;
43	  }
44	  return result;
45	}
46	
47	bool ParseBool(const std::string& value) {
48	  return value == "true" || value == "True" || value == "1";
49	}
50	
51	}  // namespace
52	
53	std::optional<StationCatalog> LoadStationCatalog(const std::filesystem::path& path) {
54	  std::ifstream input(path);
55	  if (!input) {
56	    return std::nullopt;
57	  }
58	
59	  StationCatalog catalog;
60	  Station current_station;
61	  CatalogStationEdge current_edge;
62	  std::string default_frame_id = "map";
63	  std::string section;
64	  bool in_station = false;
65	  bool in_edge = false;
66	  bool has_id = false;
67	  bool has_x = false;
68	  bool has_y = false;
69	  bool has_from = false;
70	  bool has_to = false;
71	  bool has_distance = false;
72	
73	  auto flush_station = [&]() {
74	    if (in_station && has_id && has_x && has_y) {
75	      if (current_station.frame_id.empty()) {
76	        current_station.frame_id = default_frame_id;
77	      }
78	      catalog.stations.push_back(current_station);
79	    }
80	    current_station = Station{};
81	    current_station.frame_id = default_frame_id;
82	    in_station = false;
83	    has_id = false;
84	    has_x = false;
85	    has_y = false;
86	  };
87	
88	  auto flush_edge = [&]() {
89	    if (in_edge && has_from && has_to && has_distance) {
90	      catalog.edges.push_back(current_edge);
91	    }
92	    current_edge = CatalogStationEdge{};
93	    in_edge = false;
94	    has_from = false;
95	    has_to = false;
96	    has_distance = false;
97	  };
98	
99	  std::string line;
100	  while (std::getline(input, line)) {
101	    line = Trim(line);
102	    if (line.empty() || line.front() == '#') {
103	      continue;
104	    }
105	
106	    if (line == "stations:" || line == "edges:" || line == "routes:") {
107	      flush_station();
108	      flush_edge();
109	      section = line.substr(0, line.size() - 1);
110	      continue;
111	    }
112	
113	    if (!in_station && !in_edge) {
114	      if (auto value = ValueAfterColon(line, "frame_id")) {
115	        default_frame_id = value->empty() ? "map" : *value;
116	        current_station.frame_id = default_frame_id;
117	        continue;
118	      }
119	    }
120	
121	    if (line.rfind("- ", 0) == 0) {
122	      if (section == "edges" || section == "routes") {
123	        flush_edge();
124	        in_edge = true;
125	      } else {
126	        flush_station();
127	        in_station = true;
128	        current_station.frame_id = default_frame_id;
129	      }
130	      line = Trim(line.substr(2));
131	    }
132	
133	    if (in_edge) {
134	      if (auto value = ValueAfterColon(line, "from")) {
135	        current_edge.from = *value;
136	        has_from = !current_edge.from.empty();
137	        continue;
138	      }
139	      if (auto value = ValueAfterColon(line, "to")) {
140	        current_edge.to = *value;
141	        has_to = !current_edge.to.empty();
142	        continue;
143	      }
144	      if (auto value = ValueAfterColon(line, "distance_m")) {
145	        if (auto parsed = ParseDouble(*value)) {
146	          current_edge.distance_m = *parsed;
147	          has_distance = true;
148	        }
149	        continue;
150	      }
151	      if (auto value = ValueAfterColon(line, "distance")) {
152	        if (auto parsed = ParseDouble(*value)) {
153	          current_edge.distance_m = *parsed;
154	          has_distance = true;
155	        }
156	        continue;
157	      }
158	      if (auto value = ValueAfterColon(line, "bidirectional")) {
159	        current_edge.bidirectional = ParseBool(*value);
160	        continue;
161	      }
162	      if (auto value = ValueAfterColon(line, "enabled")) {
163	        current_edge.enabled = ParseBool(*value);
164	        continue;
165	      }
166	      continue;
167	    }
168	
169	    if (auto value = ValueAfterColon(line, "id")) {
170	      current_station.id = *value;
171	      has_id = !current_station.id.empty();
172	      continue;
173	    }
174	    if (auto value = ValueAfterColon(line, "frame_id")) {
175	      current_station.frame_id = value->empty() ? default_frame_id : *value;
176	      continue;
177	    }
178	    if (auto value = ValueAfterColon(line, "x")) {
179	      if (auto parsed = ParseDouble(*value)) {
180	        current_station.x = *parsed;
181	        has_x = true;
182	      }
183	      continue;
184	    }
185	    if (auto value = ValueAfterColon(line, "y")) {
186	      if (auto parsed = ParseDouble(*value)) {
187	        current_station.y = *parsed;
188	        has_y = true;
189	      }
190	      continue;
191	    }
192	    if (auto value = ValueAfterColon(line, "yaw")) {
193	      if (auto parsed = ParseDouble(*value)) {
194	        current_station.yaw = *parsed;
195	      }
196	      continue;
197	    }
198	  }
199	  flush_station();
200	  flush_edge();
201	
202	  std::string message;
203	  if (!ValidateStationCatalog(catalog, &message)) {
204	    return std::nullopt;
205	  }
206	  return catalog;
207	}
208	
209	const Station* FindStation(const StationCatalog& catalog, const std::string& id) {
210	  for (const auto& station : catalog.stations) {
211	    if (station.id == id) {
212	      return &station;
213	    }
214	  }
215	  return nullptr;
216	}
217	
218	std::optional<double> EstimateRouteDistance(
219	    const StationCatalog& catalog, const std::string& from, const std::string& to) {
220	  const auto path = FindRoutePath(catalog, from, to);
221	  if (!path.has_value()) {
222	    return std::nullopt;
223	  }
224	  double distance_m = 0.0;
225	  for (std::size_t index = 1; index < path->size(); ++index) {
226	    for (const auto& edge : catalog.edges) {
227	      const bool forward = edge.from == (*path)[index - 1] && edge.to == (*path)[index];
228	      const bool reverse =
